1	package cli
2	
3	import (
4		"context"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"strings"
10	
11		"charm.land/huh/v2"
12		"charm.land/lipgloss/v2"
13		"github.com/spf13/cobra"
14	
15		"github.com/entireio/cli/cmd/entire/cli/auth"
16		"github.com/entireio/cli/cmd/entire/cli/interactive"
17		"github.com/entireio/cli/cmd/entire/cli/palette"
18		"github.com/entireio/cli/internal/coreapi"
19	)
20	
21	// addControlPlaneFlags registers the persistent flags shared by every
22	// control-plane command group. Persistent so they're inherited by nested
23	// subcommands (e.g. `entire repo mirror list`):
24	//   - --json: emit the raw wire JSON instead of the default human table.
25	//   - --insecure-http-auth: permit the token exchange over plain http://
26	//     (local/dev deployments where the core isn't behind TLS). Hidden, as
27	//     elsewhere in the CLI.
28	func addControlPlaneFlags(cmd *cobra.Command) {
29		cmd.PersistentFlags().Bool("json", false, "Output raw JSON instead of a table")
30		cmd.PersistentFlags().Bool("insecure-http-auth", false, "Allow authentication over plain HTTP (insecure, for local development only)")
31		if err := cmd.PersistentFlags().MarkHidden("insecure-http-auth"); err != nil {
32			panic(fmt.Sprintf("hide insecure-http-auth flag: %v", err))
33		}
34	}
35	
36	// jsonRequested reports whether --json was set on cmd or an ancestor. A
37	// lookup error means the flag isn't defined on this command tree, which is
38	// treated as "not requested".
39	func jsonRequested(cmd *cobra.Command) bool {
40		v, err := cmd.Flags().GetBool("json")
41		return err == nil && v
42	}
43	
44	// insecureHTTPRequested reports whether --insecure-http-auth was set on cmd
45	// or an ancestor.
46	func insecureHTTPRequested(cmd *cobra.Command) bool {
47		v, err := cmd.Flags().GetBool("insecure-http-auth")
48		return err == nil && v
49	}
50	
51	// addForceFlag registers the standard confirmation bypass on a destructive
52	// control-plane command: --force/-f, with --yes/-y as an alias. Either skips
53	// the prompt. Read the combined value with forceRequested.
54	func addForceFlag(cmd *cobra.Command) {
55		cmd.Flags().BoolP("force", "f", false, "Skip the confirmation prompt")
56		cmd.Flags().BoolP("yes", "y", false, "Skip the confirmation prompt (alias for --force)")
57	}
58	
59	// forceRequested reports whether the delete should skip its confirmation
60	// prompt, i.e. --force or its --yes alias was set.
61	func forceRequested(cmd *cobra.Command) bool {
62		force, ferr := cmd.Flags().GetBool("force")
63		yes, yerr := cmd.Flags().GetBool("yes")
64		return (ferr == nil && force) || (yerr == nil && yes)
65	}
66	
67	// runControlPlaneDelete is the shared body of the destructive `delete` verbs
68	// (org/project/repo). It resolves the target ref to a ULID, gates on a
69	// confirmation prompt (bypassed by --force/--yes), deletes, and reports the
70	// resolved identifier. noun names the resource ("org"); ref is the user's
71	// original argument, shown alongside the resolved ULID. resolve and del isolate
72	// the per-resource API calls.
73	func runControlPlaneDelete(
74		cmd *cobra.Command,
75		noun, ref string,
76		resolve func(context.Context, *coreapi.Client) (string, error),
77		del func(context.Context, *coreapi.Client, string) error,
78	) error {
79		force := forceRequested(cmd)
80		return runCore(cmd, func(ctx context.Context, c *coreapi.Client) error {
81			id, err := resolve(ctx, c)
82			if err != nil {
83				return err
84			}
85			label := noun + " " + resolvedRefLabel(ref, id)
86			proceed, err := confirmControlPlaneDeletion(ctx, cmd.OutOrStdout(), label, force, interactive.CanPromptInteractively())
87			if err != nil {
88				return err
89			}
90			if !proceed {
91				return nil
92			}
93			if err := del(ctx, c, id); err != nil {
94				// Idempotent delete: a resource that's already gone (a 404 from the
95				// delete call — e.g. a ULID passed straight through, or a concurrent
96				// delete) is the desired end state, not an error.
97				if isCoreNotFound(err) {
98					fmt.Fprintf(cmd.OutOrStdout(), "%s not found; nothing to delete\n", label)
99					return nil
100				}
101				return err
102			}
103			fmt.Fprintf(cmd.OutOrStdout(), "✓ Deleted %s\n", label)
104			return nil
105		})
106	}
107	
108	// confirmControlPlaneDeletion gates a destructive control-plane delete. With
109	// force it proceeds silently. Otherwise it requires an interactive terminal:
110	// with none it refuses (returns an error) rather than deleting unprompted; with
111	// one it shows a confirmation form. canPrompt is passed in (not queried) so the
112	// decision is unit-testable without a TTY. label is the human description of
113	// the target, e.g. `org acme (01J…)`.
114	func confirmControlPlaneDeletion(ctx context.Context, w io.Writer, label string, force, canPrompt bool) (bool, error) {
115		if force {
116			return true, nil
117		}
118		if !canPrompt {
119			return false, fmt.Errorf("refusing to delete %s without confirmation; pass --force", label)
120		}
121		// huh opens the TTY during form startup regardless of context state, so
122		// guard explicitly to honor an already-cancelled command context.
123		if ctx.Err() != nil {
124			return false, nil //nolint:nilerr // cancelled context is a clean skip, not an error
125		}
126		confirmed := false
127		form := NewAccessibleForm(
128			huh.NewGroup(huh.NewConfirm().Title(fmt.Sprintf("Delete %s?", label)).Value(&confirmed)),
129		)
130		if err := form.RunWithContext(ctx); err != nil {
131			// A user abort (Esc) or context cancel (Ctrl+C) is a clean cancel, not
132			// an error — mirror confirmTrailDeletion.
133			if errors.Is(err, huh.ErrUserAborted) || errors.Is(err, context.Canceled) {
134				return false, nil
135			}
136			return false, fmt.Errorf("deletion prompt: %w", err)
137		}
138		if !confirmed {
139			fmt.Fprintln(w, "Deletion cancelled.")
140			return false, nil
141		}
142		return true, nil
143	}
144	
145	// runCoreList fetches a slice via fn and renders it as an aligned table
146	// (default) or the raw wire JSON (--json). empty is the full sentence printed
147	// to stdout in place of the table when there are no items (e.g. "No
148	// organizations found."). headers names the columns; row maps one item to its
149	// cells in the same order. The human view keeps the output actionable — only
150	// the columns a person acts on — while --json preserves the full model for
151	// scripting.
152	func runCoreList[T any](cmd *cobra.Command, empty string, headers []string, row func(T) []string, fn func(ctx context.Context, c *coreapi.Client) ([]T, error)) error {
153		return runCore(cmd, renderCoreList(cmd, empty, headers, row, fn))
154	}
155	
156	// runCoreListForCluster is runCoreList for a resource-provider command (see
157	// runCoreForCluster): identical table/JSON/empty-state rendering, but dialing
158	// the core that fronts clusterHost rather than the active context.
159	func runCoreListForCluster[T any](cmd *cobra.Command, clusterHost, empty string, headers []string, row func(T) []string, fn func(ctx context.Context, c *coreapi.Client) ([]T, error)) error {
160		return runCoreForCluster(cmd, clusterHost, renderCoreList(cmd, empty, headers, row, fn))
161	}
162	
163	// renderCoreList builds the run-function shared by runCoreList and
164	// runCoreListForCluster: fetch via fn, then render as a table (default), the
165	// empty sentence (no items), or raw JSON (--json). Kept separate from the
166	// client-selection so the two list variants differ only in which core they
167	// dial.
168	func renderCoreList[T any](cmd *cobra.Command, empty string, headers []string, row func(T) []string, fn func(ctx context.Context, c *coreapi.Client) ([]T, error)) func(context.Context, *coreapi.Client) error {
169		return func(ctx context.Context, c *coreapi.Client) error {
170			items, err := fn(ctx, c)
171			if err != nil {
172				return err
173			}
174			if jsonRequested(cmd) {
175				if items == nil {
176					items = []T{} // a nil slice encodes as null; scripts expect []
177				}
178				return printJSON(cmd.OutOrStdout(), items)
179			}
180			if len(items) == 0 {
181				fmt.Fprintln(cmd.OutOrStdout(), empty)
182				return nil
183			}
184			return printTable(cmd.OutOrStdout(), headers, items, row)
185		}
186	}
187	
188	// fetchAllPages drives a keyset-paginated list endpoint to completion: it
189	// calls fetch with an empty cursor, then re-calls it with each returned
190	// nextPageToken until the cursor comes back empty, concatenating every page.
191	// The control plane caps the page size (and may cap it further than a caller
192	// requests), so a single call only returns one page — list commands must loop
193	// or they silently truncate. The next==cursor guard turns a misbehaving server
194	// that fails to advance the cursor into an error instead of an infinite loop.
195	func fetchAllPages[T any](ctx context.Context, fetch func(ctx context.Context, cursor string) (items []T, next string, err error)) ([]T, error) {
196		var all []T
197		cursor := ""
198		for {
199			items, next, err := fetch(ctx, cursor)
200			if err != nil {
201				return nil, err
202			}
203			all = append(all, items...)
204			if next == "" {
205				return all, nil
206			}
207			if next == cursor {
208				return nil, fmt.Errorf("pagination did not advance (cursor %q repeated)", next)
209			}
210			cursor = next
211		}
212	}
213	
214	// runCoreObject fetches a single value via fn and renders it as a vertical
215	// field/value list (default) or raw JSON (--json), reusing the same column
216	// definition as the matching list view.
217	func runCoreObject[T any](cmd *cobra.Command, headers []string, row func(T) []string, fn func(ctx context.Context, c *coreapi.Client) (*T, error)) error {
218		return runCore(cmd, renderCoreObject(cmd, headers, row, fn))
219	}
220	
221	// runCoreObjectForCluster is runCoreObject for a resource-provider command (see
222	// runCoreForCluster): identical field/JSON rendering, but dialing the core that
223	// fronts clusterHost rather than the active context.
224	func runCoreObjectForCluster[T any](cmd *cobra.Command, clusterHost string, headers []string, row func(T) []string, fn func(ctx context.Context, c *coreapi.Client) (*T, error)) error {
225		return runCoreForCluster(cmd, clusterHost, renderCoreObject(cmd, headers, row, fn))
226	}
227	
228	// renderCoreObject builds the run-function shared by runCoreObject and
229	// runCoreObjectForCluster: fetch via fn, then render as a field/value list
230	// (default) or raw JSON (--json). Kept separate from the client-selection so
231	// the two object variants differ only in which core they dial (mirroring
232	// renderCoreList).
233	func renderCoreObject[T any](cmd *cobra.Command, headers []string, row func(T) []string, fn func(ctx context.Context, c *coreapi.Client) (*T, error)) func(context.Context, *coreapi.Client) error {
234		return func(ctx context.Context, c *coreapi.Client) error {
235			item, err := fn(ctx, c)
236			if err != nil {
237				return err
238			}
239			if jsonRequested(cmd) {
240				return printJSON(cmd.OutOrStdout(), item)
241			}
242			return printFields(cmd.OutOrStdout(), headers, row(*item))
243		}
244	}
245	
246	// tableStyles holds the foreground styles for the human table/field views,
247	// matching the activity/session palette: gray ("8") for headers and
248	// secondary cells, white ("7") for the primary (first-column) value. When
249	// color is disabled (non-TTY, NO_COLOR — e.g. piped output and tests) the
250	// styles are no-ops and output is plain.
251	type tableStyles struct {
252		enabled bool
253		header  lipgloss.Style
254		primary lipgloss.Style
255		cell    lipgloss.Style
256	}
257	
258	func newTableStyles(w io.Writer) tableStyles {
259		if !shouldUseColor(w) {
260			return tableStyles{}
261		}
262		return tableStyles{
263			enabled: true,
264			header:  lipgloss.NewStyle().Foreground(lipgloss.Color(palette.Muted)).Bold(true),
265			primary: lipgloss.NewStyle(), // default fg: inverts with terminal theme
266			cell:    lipgloss.NewStyle().Foreground(lipgloss.Color(palette.Muted)),
267		}
268	}
269	
270	// style applies s to text only when color is enabled; otherwise it returns
271	// text unchanged so padding math and plain output stay correct.
272	func (t tableStyles) style(s lipgloss.Style, text string) string {
273		if !t.enabled {
274			return text
275		}
276		return s.Render(text)
277	}
278	
279	// columnStyle picks the foreground for a data cell: the first column is the
280	// primary identifier (white), the rest are secondary (gray).
281	func (t tableStyles) columnStyle(col int) lipgloss.Style {
282		if col == 0 {
283			return t.primary
284		}
285		return t.cell
286	}
287	
288	// printTable writes headers plus one row per item, columns aligned on the
289	// plain-text widths so ANSI color codes don't throw off the layout (they're
290	// applied after padding). Callers handle the empty case.
291	func printTable[T any](w io.Writer, headers []string, items []T, row func(T) []string) error {
292		st := newTableStyles(w)
293		rows := make([][]string, len(items))
294		for i, it := range items {
295			rows[i] = row(it)
296		}
297		widths := columnWidths(headers, rows)
298	
299		var b strings.Builder
300		writeTableRow(&b, headers, widths, func(int) lipgloss.Style { return st.header }, st)
301		for _, r := range rows {
302			writeTableRow(&b, r, widths, st.columnStyle, st)
303		}
304		if _, err := io.WriteString(w, b.String()); err != nil {
305			return fmt.Errorf("render table: %w", err)
306		}
307		return nil
308	}
309	
310	// printFields writes a single record as aligned "FIELD  value" lines: the
311	// label in header gray, the value in the same primary/secondary color the
312	// list view would give that column.
313	func printFields(w io.Writer, headers, values []string) error {
314		st := newTableStyles(w)
315		labelWidth := 0
316		for _, h := range headers {
317			if n := lipgloss.Width(h); n > labelWidth {
318				labelWidth = n
319			}
320		}
321		var b strings.Builder
322		for i, h := range headers {
323			var v string
324			if i < len(values) {
325				v = values[i]
326			}
327			label := st.style(st.header, h+strings.Repeat(" ", labelWidth-lipgloss.Width(h)))
328			b.WriteString(label)
329			b.WriteString("  ")
330			b.WriteString(st.style(st.columnStyle(i), v))
331			b.WriteByte('\n')
332		}
333		if _, err := io.WriteString(w, b.String()); err != nil {
334			return fmt.Errorf("render fields: %w", err)
335		}
336		return nil
337	}
338	
339	// columnWidths returns the max plain-text width of each column across the
340	// headers and all rows.
341	func columnWidths(headers []string, rows [][]string) []int {
342		widths := make([]int, len(headers))
343		for i, h := range headers {
344			widths[i] = lipgloss.Width(h)
345		}
346		for _, r := range rows {
347			for i, c := range r {
348				if i < len(widths) && lipgloss.Width(c) > widths[i] {
349					widths[i] = lipgloss.Width(c)
350				}
351			}
352		}
353		return widths
354	}
355	
356	// writeTableRow pads each cell to its column width on the plain text, then
357	// styles it — so alignment is computed before any ANSI codes are added.
358	// The final column isn't padded, avoiding trailing whitespace.
359	func writeTableRow(b *strings.Builder, cells []string, widths []int, styleFor func(col int) lipgloss.Style, st tableStyles) {
360		for i, c := range cells {
361			last := i == len(cells)-1
362			padded := c
363			if !last && i < len(widths) {
364				padded = c + strings.Repeat(" ", widths[i]-lipgloss.Width(c))
365			}
366			b.WriteString(st.style(styleFor(i), padded))
367			if !last {
368				b.WriteString("  ")
369			}
370		}
371		b.WriteByte('\n')
372	}
373	
374	// runCoreMutation runs fn against the control plane and renders its outcome
375	// the way the rest of the CLI renders mutations: prints the caller's
376	// ✓-prefixed confirmation on stdout by default, or the wire object as JSON
377	// when --json was passed. fn
378	// returns both so the human line can name the created resource while --json
379	// preserves the full wire model (additive-only: synthesized fields like the
380	// repo remote URL are merged in, nothing is ever omitted). It owns the same
381	// preamble as the other runCore variants: silence usage, build the client,
382	// map API errors to problem-detail messages.
383	func runCoreMutation(cmd *cobra.Command, fn func(ctx context.Context, c *coreapi.Client) (message string, wire any, err error)) error {
384		return runCore(cmd, func(ctx context.Context, c *coreapi.Client) error {
385			message, wire, err := fn(ctx, c)
386			if err != nil {
387				return err
388			}
389			if jsonRequested(cmd) {
390				return printJSON(cmd.OutOrStdout(), wire)
391			}
392			fmt.Fprintln(cmd.OutOrStdout(), message)
393			return nil
394		})
395	}
396	
397	// activeCoreClient builds the control-plane client for active-context
398	// commands. A package-level seam (production wiring is coreapi.New) so
399	// command-level tests can point the whole command tree at an httptest server
400	// without standing up the auth/context/TLS stack.
401	var activeCoreClient = func(context.Context) (*coreapi.Client, error) { return coreapi.New() }
402	
403	// clusterCoreClient builds the control-plane client for cluster-addressed
404	// commands (see runCoreForCluster). Same test seam as activeCoreClient —
405	// production wiring is coreapi.NewForCluster, which does live /.well-known
406	// discovery that command-level tests must not reach.
407	var clusterCoreClient func(ctx context.Context, clusterHost string) (*coreapi.Client, error) = coreapi.NewForCluster
408	
409	// runCore is the shared base for every active-context control-plane command:
410	// it owns the preamble only — silence usage, build the client, map API
411	// errors — and leaves all rendering to fn. The delete/revoke verbs call it
412	// directly and render their own output; runCoreList, runCoreObject, and
413	// runCoreMutation build on it to add their table/JSON/confirmation
414	// rendering. The client dials the active context's core (coreapi.New); use
415	// runCoreForCluster for commands addressed at a specific cluster.
416	func runCore(cmd *cobra.Command, fn func(ctx context.Context, c *coreapi.Client) error) error {
417		return runCoreClient(cmd, activeCoreClient, fn)
418	}
419	
420	// runCoreForCluster is runCore for resource-provider commands addressed at a
421	// specific cluster (mirror create/remove, mirror collaborators list):
422	// it dials the core that fronts clusterHost — discovered from the cluster's
423	// /.well-known/entire-cluster.json, authenticating with the matching local
424	// context — instead of the active context. So the command works on a cluster in
425	// a federation other than the active login, instead of failing with "unknown
426	// cluster_host". See coreapi.NewForCluster.
427	func runCoreForCluster(cmd *cobra.Command, clusterHost string, fn func(ctx context.Context, c *coreapi.Client) error) error {
428		return runCoreClient(cmd, func(ctx context.Context) (*coreapi.Client, error) {
429			return clusterCoreClient(ctx, clusterHost)
430		}, fn)
431	}
432	
433	// runCoreClient owns the control-plane preamble shared by the active-context
434	// (runCore) and cluster-addressed (runCoreForCluster) variants: silence usage,
435	// opt into plain-HTTP token exchange if requested, build the client via
436	// newClient, run fn, and map API errors. The only difference between the two
437	// variants is which core newClient dials.
438	func runCoreClient(cmd *cobra.Command, newClient func(context.Context) (*coreapi.Client, error), fn func(ctx context.Context, c *coreapi.Client) error) error {
439		cmd.SilenceUsage = true
440		// Opt into plain-HTTP token exchange before the client (and its lazily
441		// built token manager) is constructed — the manager freezes the
442		// setting on first use.
443		if insecureHTTPRequested(cmd) {
444			auth.EnableInsecureHTTP()
445		}
446		client, err := newClient(cmd.Context())
447		if err != nil {
448			return fmt.Errorf("connect to Entire control plane: %w", err)
449		}
450		if err := fn(cmd.Context(), client); err != nil {
451			return renderCoreError(err)
452		}
453		return nil
454	}
455	
456	// markRequired marks one or more flags required, panicking if a name
457	// doesn't exist — that can only happen from a typo at wiring time, never
458	// at runtime, so a panic surfaces the bug immediately rather than letting
459	// a "required" flag silently not be enforced.
460	func markRequired(cmd *cobra.Command, names ...string) {
461		for _, name := range names {
462			if err := cmd.MarkFlagRequired(name); err != nil {
463				panic(fmt.Sprintf("mark flag %q required: %v", name, err))
464			}
465		}
466	}
467	
468	// renderCoreError converts a Core API error into the server's
469	// problem-detail message (so users see "organization name already taken"
470	// rather than ogen's decode-wrapped string), falling back to the raw error
471	// for transport/local failures. It returns a plain error, not a
472	// SilentError: main.go prints plain errors, and runCore has already set
473	// SilenceUsage, so the message reaches the user without a usage dump. (A
474	// SilentError here would be swallowed — main.go skips printing those —
475	// leaving e.g. a 409 conflict with no output.)
476	func renderCoreError(err error) error {
477		if err == nil {
478			return nil
479		}
480		if msg := coreapi.APIError(err); msg != "" {
481			return errors.New(msg)
482		}
483		return err
484	}
485	
486	// printJSON writes v as indented JSON to w — the --json view for list/get
487	// and mutations.
488	func printJSON(w io.Writer, v any) error {
489		enc := json.NewEncoder(w)
490		enc.SetIndent("", "  ")
491		if err := enc.Encode(v); err != nil {
492			return fmt.Errorf("encode output: %w", err)
493		}
494		return nil
495	}
