360	// mirrorCreateOutcome bundles the create response with the clone status
361	// observed while waiting. polled is false for --no-wait and for empty upstreams,
362	// where there is nothing to await; in those cases status is unset.
363	type mirrorCreateOutcome struct {
364		created *coreapi.CreatedMirror
365		status  coreapi.MirrorStatus
366		polled  bool
367	}
368	
369	// createAndAwaitMirror is the single create-then-wait path shared by the
370	// `repo mirror create <github-url>` one-shot and the onboarding wizard, so both
371	// report identical lifecycle states. It registers the GitHub mirror on
372	// clusterHost (idempotent on (upstream, cluster)) and, unless noWait or the
373	// upstream is empty, polls the control plane until the clone reaches a terminal
374	// status. The returned error is the create error (when outcome.created is nil)
375	// or the wait error — a status sentinel (errMirrorCloneFailed /
376	// errMirrorSuspended) or a timeout; callers read outcome.status for the state.
377	//
378	// onCreated (may be nil) fires once the placement is registered, before any
379	// clone polling — it separates the fast "placing" phase from the slow "cloning"
380	// wait so callers can render them as distinct steps.
381	func createAndAwaitMirror(ctx context.Context, c *coreapi.Client, owner, repo, clusterHost string, noWait bool, timeout time.Duration, onCreated func(*coreapi.CreatedMirror), onStatus func(coreapi.MirrorStatus)) (mirrorCreateOutcome, error) {
382		created, err := c.CreateMirror(ctx, &coreapi.CreateMirrorInputBody{
383			Provider:    coreapi.CreateMirrorInputBodyProviderGithub,
384			Owner:       owner,
385			Repo:        repo,
386			ClusterHost: clusterHost,
387		})
388		if err != nil {
389			return mirrorCreateOutcome{}, err
390		}
391		if onCreated != nil {
392			onCreated(created)
393		}
394		outcome := mirrorCreateOutcome{created: created}
395		if created.Suspended {
396			// The placement already existed and an admin has suspended it, so it
397			// will never serve — skip the clone poll. The caller warns after echoing
398			// the placement; a suspended re-create is still a (non-fatal) success,
399			// so return no error.
400			return outcome, nil
401		}
402		if created.Empty {
403			// An empty upstream has nothing to clone, so don't poll for "ready" — it
404			// never would. But an *existing* placement can be suspended even when
405			// empty, and one status read surfaces that (a fresh create can't be
406			// suspended — suspension follows upstream access loss). Mirrors the old
407			// finishMirrorCreate behavior; the read is best-effort, so a transient
408			// GetMirror error just falls through to the benign "nothing to clone".
409			if !created.Created {
410				if m, gerr := c.GetMirror(ctx, coreapi.GetMirrorParams{MirrorId: created.MirrorId}); gerr == nil {
411					if s, ok := m.Status.Get(); ok && s == coreapi.MirrorStatusSuspended {
412						outcome.status = s
413						outcome.polled = true
414						return outcome, errMirrorSuspended
415					}
416				}
417			}
418			return outcome, nil
419		}
420		if noWait {
421			return outcome, nil
422		}
423		status, werr := awaitMirrorReady(ctx, c, created.MirrorId, timeout, onStatus)
424		outcome.status = status
425		outcome.polled = true
426		return outcome, werr
427	}
428	
429	// reportOneShotMirror renders the human output for `repo mirror create
430	// <github-url>` from the shared createAndAwaitMirror result. A nil
431	// outcome.created means CreateMirror itself failed — surface that error (nothing
432	// was printed yet). Otherwise echo the placement, then the lifecycle outcome.
433	func reportOneShotMirror(out, errW io.Writer, outcome mirrorCreateOutcome, err error) error {
434		created := outcome.created
435		if created == nil {
436			return err
437		}
438		if created.Created {
439			fmt.Fprintf(out, "\n✓ Registered mirror %s\n", created.MirrorId)
440		} else {
441			fmt.Fprintf(out, "\nMirror exists (%s)\n", created.MirrorId)
442		}
443		fmt.Fprintf(out, "  %s\n", created.MirrorUrl)
444	
445		if created.Suspended {
446			// Echo the placement (above), warn, and exit non-zero: the mirror can't
447			// be used, so a script chaining a clone shouldn't treat this as success.
448			// SilentError keeps main.go from reprinting — the warning is the message.
449			fmt.Fprintln(errW, "\nWARNING: this mirror has been suspended by an admin and won't be usable.")
450			return NewSilentError(errMirrorSuspended)
451		}
452	
453		if !outcome.polled {
454			if created.Empty {
455				fmt.Fprintln(out, "Upstream has no commits yet — nothing to clone. The mirror will pick up refs once the upstream is pushed to.")
456			} else {
457				fmt.Fprintf(out, "Initial clone may still be in progress; `git clone %s` will work once it completes.\n", created.MirrorUrl)
458			}
459			return nil
460		}
461	
462		switch outcome.status {
463		case coreapi.MirrorStatusReady:
464			fmt.Fprintf(out, "\nClone it:\n  git clone %s\n", created.MirrorUrl)
465			return nil
466		case coreapi.MirrorStatusSuspended:
467			explainSuspendedMirror(errW, created.MirrorId)
468			return NewSilentError(errMirrorSuspended)
469		case coreapi.MirrorStatusFailed:
470			return fmt.Errorf("initial clone of mirror %s failed", created.MirrorId)
471		case coreapi.MirrorStatusProcessing:
472			// Still processing when the poll returned: the wait timed out (or a
473			// poll call errored). awaitMirrorReady's err carries which. Route it
474			// through renderCoreError so an API error (e.g. a 404 problem+json)
475			// renders as the server's Detail rather than ogen's raw decoded struct;
476			// a timeout error passes through unchanged.
477			return renderCoreError(err)
478		default:
479			return renderCoreError(err)
480		}
481	}
